class Solution {
public:
    vector<vector<int>> rotateGrid(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        int numLayers = min(m, n) / 2;
        for (int layer = 0; layer < numLayers; layer++) {
            int r1 = layer, r2 = m - 1 - layer;
            int c1 = layer, c2 = n - 1 - layer;
            vector<pair<int, int>> coords;
            for (int c = c1; c < c2; c++) coords.push_back({r1, c});
            for (int r = r1; r < r2; r++) coords.push_back({r, c2});
            for (int c = c2; c > c1; c--) coords.push_back({r2, c});
            for (int r = r2; r > r1; r--) coords.push_back({r, c1});

            int len = coords.size();
            int shift = k % len;
            vector<int> vals(len);
            for (int i = 0; i < len; i++) vals[i] = grid[coords[i].first][coords[i].second];
            for (int i = 0; i < len; i++) {
                grid[coords[i].first][coords[i].second] = vals[(i + shift) % len];
            }
        }
        return grid;
    }
};

class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int numLayers = Math.min(m, n) / 2;
        for (int layer = 0; layer < numLayers; layer++) {
            int r1 = layer, r2 = m - 1 - layer;
            int c1 = layer, c2 = n - 1 - layer;
            List<int[]> coords = new ArrayList<>();
            for (int c = c1; c < c2; c++) coords.add(new int[]{r1, c});
            for (int r = r1; r < r2; r++) coords.add(new int[]{r, c2});
            for (int c = c2; c > c1; c--) coords.add(new int[]{r2, c});
            for (int r = r2; r > r1; r--) coords.add(new int[]{r, c1});

            int len = coords.size();
            int shift = k % len;
            int[] vals = new int[len];
            for (int i = 0; i < len; i++) vals[i] = grid[coords.get(i)[0]][coords.get(i)[1]];
            for (int i = 0; i < len; i++) {
                grid[coords.get(i)[0]][coords.get(i)[1]] = vals[(i + shift) % len];
            }
        }
        return grid;
    }
}

var rotateGrid = function(grid, k) {
  const m = grid.length, n = grid[0].length;
  const numLayers = Math.floor(Math.min(m, n) / 2);
  for (let layer = 0; layer < numLayers; layer++) {
    const r1 = layer, r2 = m - 1 - layer;
    const c1 = layer, c2 = n - 1 - layer;
    const coords = [];
    for (let c = c1; c < c2; c++) coords.push([r1, c]);
    for (let r = r1; r < r2; r++) coords.push([r, c2]);
    for (let c = c2; c > c1; c--) coords.push([r2, c]);
    for (let r = r2; r > r1; r--) coords.push([r, c1]);

    const len = coords.length;
    const shift = k % len;
    const vals = coords.map(([r, c]) => grid[r][c]);
    for (let i = 0; i < len; i++) {
      grid[coords[i][0]][coords[i][1]] = vals[(i + shift) % len];
    }
  }
  return grid;
};
